/**
 * A small Markdown renderer for kit descriptions, guides and policy
 * documents. It builds React elements only - no HTML string, no
 * dangerouslySetInnerHTML - so markup in the text stays text.
 *
 * Supported: headings (##, ###), paragraphs, lists (-, 1.), task lists,
 * fenced code, inline code, bold, links, tables, quotes, rules. Links: only
 * http(s) and paths on this site; outside links open in a new tab with
 * noopener noreferrer nofollow; anything else (javascript:, data:) stays
 * text. Images are not drawn. Scrollable code and tables take keyboard focus.
 */
import { Fragment, type ReactNode } from 'react'

function safeHref(href: string): { href: string; external: boolean } | null {
  const h = href.trim()
  if (/^\/(?!\/)/.test(h)) return { href: h, external: false }
  try {
    const u = new URL(h)
    if (u.protocol === 'https:' || u.protocol === 'http:') return { href: u.toString(), external: true }
  } catch {
    /* 링크로 만들지 않는다 */
  }
  return null
}

function inline(text: string, keyBase: string): ReactNode[] {
  const out: ReactNode[] = []
  const re = /(`[^`]+`)|(\*\*[^*]+\*\*)|(\[[^\]]+\]\([^)\s]+\))/g
  let last = 0
  let m: RegExpExecArray | null
  let i = 0
  while ((m = re.exec(text))) {
    if (m.index > last) out.push(text.slice(last, m.index))
    const tok = m[0]
    const key = `${keyBase}-${i++}`
    if (tok.startsWith('`')) out.push(<code key={key}>{tok.slice(1, -1)}</code>)
    else if (tok.startsWith('**')) out.push(<strong key={key}>{tok.slice(2, -2)}</strong>)
    else {
      const lm = /^\[([^\]]+)\]\(([^)\s]+)\)$/.exec(tok)!
      const link = safeHref(lm[2]!)
      out.push(
        link ? (
          <a key={key} href={link.href} {...(link.external ? { target: '_blank', rel: 'noopener noreferrer nofollow' } : {})}>
            {lm[1]}
          </a>
        ) : (
          <span key={key}>{lm[1]}</span>
        ),
      )
    }
    last = m.index + tok.length
  }
  if (last < text.length) out.push(text.slice(last))
  return out
}

function splitRow(line: string): string[] {
  const t = line.trim().replace(/^\|/, '').replace(/\|$/, '')
  const cells: string[] = []
  let cur = ''
  for (let i = 0; i < t.length; i++) {
    if (t[i] === '\\' && t[i + 1] === '|') {
      cur += '|'
      i++
    } else if (t[i] === '|') {
      cells.push(cur.trim())
      cur = ''
    } else cur += t[i]
  }
  cells.push(cur.trim())
  return cells
}

export function Markdown({ source, className = 'bz-prose' }: { source: string; className?: string }) {
  const lines = (source ?? '').replace(/\r\n?/g, '\n').split('\n')
  const blocks: ReactNode[] = []
  let i = 0
  let k = 0
  while (i < lines.length) {
    const line = lines[i]!
    const key = `b${k++}`
    if (/^```/.test(line)) {
      const body: string[] = []
      i++
      while (i < lines.length && !/^```/.test(lines[i]!)) body.push(lines[i++]!)
      i++
      // 가로로 스크롤되는 코드 블록은 키보드로도 스크롤할 수 있게 초점을 받는다
      blocks.push(
        <pre key={key} tabIndex={0}>
          <code>{body.join('\n')}</code>
        </pre>,
      )
      continue
    }
    if (!line.trim()) {
      i++
      continue
    }
    const h = /^(#{1,4})\s+(.*)$/.exec(line)
    if (h) {
      const level = Math.min(4, h[1]!.length + 1)
      const content = inline(h[2]!, key)
      blocks.push(level === 2 ? <h2 key={key}>{content}</h2> : level === 3 ? <h3 key={key}>{content}</h3> : <h4 key={key}>{content}</h4>)
      i++
      continue
    }
    if (/^(-{3,}|\*{3,})\s*$/.test(line)) {
      blocks.push(<hr key={key} />)
      i++
      continue
    }
    if (/^\s*\|/.test(line) && i + 1 < lines.length && /^\s*\|?\s*:?-{3,}/.test(lines[i + 1]!)) {
      const head = splitRow(line)
      i += 2
      const rows: string[][] = []
      while (i < lines.length && /^\s*\|/.test(lines[i]!)) rows.push(splitRow(lines[i++]!))
      blocks.push(
        <div key={key} className="bz-table-scroll" tabIndex={0}>
        <table>
          <thead>
            <tr>{head.map((c, j) => <th key={j}>{inline(c, `${key}h${j}`)}</th>)}</tr>
          </thead>
          <tbody>
            {rows.map((r, ri) => (
              <tr key={ri}>{r.map((c, j) => <td key={j}>{inline(c, `${key}r${ri}c${j}`)}</td>)}</tr>
            ))}
          </tbody>
        </table>
        </div>,
      )
      continue
    }
    if (/^>\s?/.test(line)) {
      const body: string[] = []
      while (i < lines.length && /^>\s?/.test(lines[i]!)) body.push(lines[i++]!.replace(/^>\s?/, ''))
      blocks.push(<blockquote key={key}>{inline(body.join(' '), key)}</blockquote>)
      continue
    }
    if (/^\s*([-*]|\d+\.)\s+/.test(line)) {
      const ordered = /^\s*\d+\./.test(line)
      const items: { text: string; sub: string[] }[] = []
      while (i < lines.length && (/^\s*([-*]|\d+\.)\s+/.test(lines[i]!) || /^\s{2,}\S/.test(lines[i]!))) {
        const l = lines[i]!
        if (/^\s{2,}([-*])\s+/.test(l) && items.length) items[items.length - 1]!.sub.push(l.replace(/^\s+[-*]\s+/, ''))
        else if (/^\s{2,}\S/.test(l) && !/^\s*([-*]|\d+\.)\s+/.test(l) && items.length) items[items.length - 1]!.text += ` ${l.trim()}`
        else items.push({ text: l.replace(/^\s*([-*]|\d+\.)\s+/, ''), sub: [] })
        i++
      }
      const lis = items.map((it, j) => {
        const task = /^\[( |x)\]\s+/i.exec(it.text)
        return (
          <li key={j} className={task ? 'task' : undefined}>
            {task ? <span aria-hidden="true">{task[1] === ' ' ? '☐ ' : '☑ '}</span> : null}
            {inline(task ? it.text.slice(task[0].length) : it.text, `${key}i${j}`)}
            {it.sub.length ? (
              <ul>
                {it.sub.map((s, si) => (
                  <li key={si}>{inline(s, `${key}i${j}s${si}`)}</li>
                ))}
              </ul>
            ) : null}
          </li>
        )
      })
      blocks.push(ordered ? <ol key={key}>{lis}</ol> : <ul key={key}>{lis}</ul>)
      continue
    }
    const para: string[] = []
    while (i < lines.length && lines[i]!.trim() && !/^(#{1,4}\s|```|>\s?|\s*([-*]|\d+\.)\s+|\s*\|)/.test(lines[i]!)) para.push(lines[i++]!)
    if (para.length === 0) {
      para.push(lines[i++]!)
    }
    blocks.push(
      <p key={key}>
        {para.map((p, j) => (
          <Fragment key={j}>
            {j > 0 ? <br /> : null}
            {inline(p, `${key}p${j}`)}
          </Fragment>
        ))}
      </p>,
    )
  }
  return <div className={className}>{blocks}</div>
}
