describe('agent and MCP tools', () => {
  const router = buildRouter()
  const sample: Record<string, unknown> = { id: '00000000-0000-4000-8000-000000000000', invoice_id: '00000000-0000-4000-8000-000000000000' }

  it('every tool calls a route that exists, with the right method, on a company path', () => {
    for (const tool of TOOLS) {
      const call = tool.call(sample)
      const concrete = call.path.replace(':ws', 'acme').replace(/:([a-zA-Z]+)/g, (_, n: string) => String(call.params?.[n] ?? 'x'))
      const matched = router.match(call.method, concrete)
      expect(matched && !('allow' in matched), `${tool.name} -> ${call.method} ${call.path}`).toBe(true)
      if (matched && 'route' in matched) {
        expect(matched.route.tenant, tool.name).toBe(true)
        if (tool.kind === 'read') expect(matched.route.readOnly, `${tool.name} reads in a read-only transaction`).toBe(true)
      }
    }
  })

  it('names are unique, writes say what they will do, approve tools reach the approve-scoped routes', () => {
    expect(new Set(TOOLS.map((t) => t.name)).size).toBe(TOOLS.length)
    for (const t of TOOLS.filter((x) => x.kind !== 'read')) expect(typeof t.summary, t.name).toBe('function')
    for (const t of TOOLS.filter((x) => x.kind === 'approve')) {
      const call = t.call(sample)
      const matched = router.match(call.method, call.path.replace(':ws', 'acme').replace(':id', String(sample.id)))
      expect(matched && 'route' in matched ? matched.route.tokenScope : null, t.name).toBe('approve')
    }
  })

  it('compacts answers for the model', () => {
    const out = compact({ a: '', b: null, c: 'x'.repeat(700), d: Array.from({ length: 45 }, (_, i) => i), e: [] }) as Record<string, unknown>
    expect(out.a).toBeUndefined()
    expect(out.b).toBeUndefined()
    expect(String(out.c).length).toBe(601)
    expect((out.d as unknown[]).length).toBe(41)
    expect(out.e).toBeUndefined()
  })

  it('reads both model answer shapes and drops <think>', () => {
    const a = normalize({ choices: [{ message: { content: '<think>hm</think>답', tool_calls: [{ id: 'c1', function: { name: 'get_todo', arguments: '{}' } }] } }] })
    expect(a.text).toBe('답')
    expect(a.toolCalls[0]).toMatchObject({ id: 'c1', name: 'get_todo', args: {} })
    const b = normalize({ response: '', tool_calls: [{ name: 'search_customers', arguments: { q: '가' } }] })
    expect(b.toolCalls[0]?.args).toEqual({ q: '가' })
    expect(parseArgs('{"a":1}{"b":2}')).toBeNull()
    expect(parseArgs('')).toEqual({})
  })
})

describe('approval rules', () => {
