    const steps = validateRuleSteps([
      { seq: 2, kind: 'approve', assignee: { type: 'role', value: 'owner' }, final_allowed: true },
      { seq: 1, kind: 'agree', assignee: { type: 'dept_head' }, final_allowed: true },
    ])
    expect(steps.map((s) => s.seq)).toEqual([1, 2])
    expect(steps[0]!.final_allowed).toBe(false)
    expect(() => validateRuleSteps([{ seq: 1, kind: 'reference', assignee: { type: 'dept_head' } }])).toThrow()
    expect(() => validateRuleSteps([{ seq: 1, kind: 'approve', assignee: { type: 'role' } }])).toThrow()
    expect(() => validateRuleSteps([])).toThrow()
  })

  it('renumbers turns 1..n keeping parallel steps together', () => {
    const out = renumber([
      { seq: 5, kind: 'approve', member_id: 'a', final_allowed: false, locked: false },
      { seq: 9, kind: 'approve', member_id: 'b', final_allowed: false, locked: false },
      { seq: 5, kind: 'agree', member_id: 'c', final_allowed: false, locked: false },
