describe('agent wording and dates', () => {
  it('gives the model a calendar to read, in Korea time', () => {
    // 2026-10-07 (Wed) 23:30 UTC is already Thursday 10-08 in Seoul.
    const text = dateContext(Date.UTC(2026, 9, 7, 23, 30))
    expect(text).toContain('오늘: 2026-10-08(목)')
    expect(text).toContain('이번 주(월~일): 2026-10-05(월)')
